const competitors = $("Load Competitors").all().map(i => i.json);
const cfgRow = $("Load SOV Config").first();
const config = (cfgRow && cfgRow.json && cfgRow.json.config) ? cfgRow.json.config : {};
const active = competitors.filter(c => c.active !== false);
const companies = active.map(c => ({ name: c.name, keywords: Array.isArray(c.keywords)?c.keywords:[], definition: c.definition||'', collision_terms: Array.isArray(c.collision_terms)?c.collision_terms:[], aliases: Array.isArray(c.aliases) ? c.aliases : [], domain: c.domain || null, x_handle: c.x_handle || null, linkedin_urn: c.linkedin_urn || null, subreddits: Array.isArray(c.subreddits) ? c.subreddits : [], type: c.type || 'direct' }));
const linkedin_urns = companies.map(c => c.linkedin_urn).filter(Boolean);
const companyEnum = companies.map(c => c.name).join(", ");
const allSubreddits = Array.from(new Set([].concat(...companies.map(c => c.subreddits)).concat(["cybersecurity","netsec","asknetsec","devsecops","hacking","information_security","security","identitymanagement","sysadmin","itmanagers","blueteamsec"]))).filter(Boolean);
return [{ json: { config, companies, linkedin_urns, companyEnum, allSubreddits } }];

const ctx = $("Build Context").first().json;
// DIRECT competitors only. HYBRID handle-first: (A) from:<handle> timeline; (B) one GUARDED mention query
// per co (quoted phrase + static negations + DYNAMIC learned negations from sov_config.xNegations + lang:en).
// NEVER an OR-blob. One Apify run. Learned negations self-tune the queries to the junk they actually hit.
const companies = (ctx.companies || []).filter(c => c && (c.type || 'direct') === 'direct');
const cfg = ctx.config || {};
const NEG = (cfg.xNegations && typeof cfg.xNegations === 'object') ? cfg.xNegations : {};
const start = $now.minus({ days: 1 }).toISODate();
const GUARD = {
  'Surf AI':        { phrase: '"Surf AI" OR "Surf Security"',                          neg: '-surfshark -asksurf -crypto -token -airdrop -aviation' },
  'Lumos':          { phrase: '"Lumos identity" OR "Lumos IGA" OR "Lumos IAM"',          neg: '-"harry potter" -crypto -token -proton -lumosity -fiber' },
  'Opti':           { phrase: '"Opti identity" OR "Opti IAM" OR "opti.ai"',              neg: '-optiv -optimizely' },
  'Console':        { phrase: '"Console ITSM" OR "Console identity" OR "console.com"',    neg: '-playstation -xbox -nintendo' },
  'Torch Security': { phrase: '"Torch Security" OR "torch.security"',                    neg: '-pytorch -flashlight' },
  '7AI':            { phrase: '"7AI" OR "7ai.com"',                                      neg: '-247' },
  'OFFROAD':        { phrase: '"Offroad Security" OR "offroad.ai"',                      neg: '-jeep -4x4 -overlanding -truck' },
  'Twine Security': { phrase: '"Twine Security" OR "Twine identity"',                    neg: '-"digital twin" -tupperware -twinery' }
};
const seen = new Set();
const searchTerms = [];
function push(q){ const k = q.toLowerCase(); if (!seen.has(k)) { seen.add(k); searchTerms.push(q); } }
for (const c of companies) {
  const name = (c.name == null ? "" : String(c.name)).trim();
  if (!name) continue;
  let handle = c.x_handle ? String(c.x_handle).trim().replace(/^@/, "") : "";
  if (handle && !/^[A-Za-z0-9_]{1,15}$/.test(handle)) handle = "";
  if (handle) push('from:' + handle + ' lang:en');
  const g = GUARD[name];
  const core = g ? g.phrase : ((c.keywords&&c.keywords.length) ? c.keywords.map(k=>'"'+k+'"').join(' OR ') : ('"' + name + '"'));
  const handleClause = handle ? ('@' + handle + ' OR ') : '';
  let neg = (g && g.neg) ? (' ' + g.neg) : '';
  const learned = Array.isArray(NEG[name]) ? NEG[name] : [];
  for (const t of learned) { const tok = String(t || '').trim(); if (tok) neg += ' -' + tok; }
  push('(' + handleClause + core + ')' + neg + ' lang:en');
}
return [{ json: { searchTerms, start } }];

// Flatten + dedup the Apify tweets, then chunk into batches of 50 (one item per chunk) so the LLM node
// runs a few times, not once-per-tweet — bounded memory (the OOM-safe Processor pattern).
const BATCH = 50, MAXTEXT = 400;
const ctx = $("Build Context").first().json;
const companies = (ctx.companies || []).map(c => ({ name: c.name, x_handle: c.x_handle || null }));
const companyEnum = companies.map(c => c.name).join(', ');
const companyDefs = companies.map(c=>{const dom=c.domain?(' ('+c.domain+')'):'';const nots=(c.collision_terms&&c.collision_terms.length)?('. NOT: '+c.collision_terms.join('; ')):'';return c.name+dom+' \u2014 '+(c.definition||'(no definition yet)')+nots;}).join('\n\n');
const seen = {}; const flat = [];
for (const item of $input.all()) {
  const t = item.json || {}; const id = t.id || t.tweetId || t.rest_id; if (!id || seen[id]) continue; seen[id] = 1;
  const a = t.author || {}; const followers = Number(a.followers || 0); const viewCount = Number(t.viewCount || t.views || 0);
  let bw = 1; if (followers >= 100000) bw = 6; else if (followers >= 10000) bw = 5; else if (followers >= 1000) bw = 4; else if (followers >= 500) bw = 3; else if (followers >= 50) bw = 2;
  let authorWeight = bw; if (a.isVerified || a.isBlueVerified) authorWeight = bw < 5 ? bw + 1 : 5;
  const authorUserName = (a.userName || a.username || a.screenName || a.screen_name || '');
  flat.push({ id: String(id), twitterUrl: t.url || '', url: t.url || '', text: t.text || '', createdAt: t.createdAt || '', likeCount: Number(t.likeCount || 0), retweetCount: Number(t.retweetCount || 0), replyCount: Number(t.replyCount || 0), quoteCount: Number(t.quoteCount || 0), viewCount, followers, authorWeight, authorUserName });
}
if (!flat.length) return [];
const out = [];
for (let i = 0; i < flat.length; i += BATCH) {
  const chunk = flat.slice(i, i + BATCH);
  const llmPosts = chunk.map(t => ({ id: t.id, text: String(t.text || '').slice(0, MAXTEXT), authorUserName: t.authorUserName }));
  out.push({ json: { chunkIndex: i / BATCH, companyEnum, companyDefs, companies, llmPosts, full: chunk } });
}
return out;

const results = [];
function llmText(j){
  if (j && Array.isArray(j.output)) { for (const mm of j.output) { if (mm && Array.isArray(mm.content)) { for (const c of mm.content) { if (c && typeof c.text === 'string') return c.text; } } } }
  if (j && typeof j.text === 'string') return j.text;
  if (j && typeof j.content === 'string') return j.content;
  if (j && j.message && typeof j.message.content === 'string') return j.message.content;
  if (j && Array.isArray(j.choices) && j.choices[0]) { const ch = j.choices[0]; if (ch.message && (ch.message.content || ch.message.reasoning)) return ch.message.content || ch.message.reasoning; if (typeof ch.text === 'string') return ch.text; }
  return '';
}
for (const item of $input.all()) {
  let raw = String(llmText(item.json) || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  if (!raw) continue;
  const a = raw.indexOf('['); const b = raw.lastIndexOf(']');
  if (a === -1 || b === -1 || b <= a) continue;
  let parsed; try { parsed = JSON.parse(raw.slice(a, b + 1)); } catch (e) { continue; }
  const arr = Array.isArray(parsed) ? parsed : [parsed];
  for (const e of arr) { if (e && e.id) results.push({ json: e }); }
}
return results;

const results = [];
function llmText(j){
  if (j && Array.isArray(j.output)) { for (const mm of j.output) { if (mm && Array.isArray(mm.content)) { for (const c of mm.content) { if (c && typeof c.text === 'string') return c.text; } } } }
  if (j && typeof j.text === 'string') return j.text;
  if (j && typeof j.content === 'string') return j.content;
  if (j && j.message && typeof j.message.content === 'string') return j.message.content;
  if (j && Array.isArray(j.choices) && j.choices[0]) { const ch = j.choices[0]; if (ch.message && (ch.message.content || ch.message.reasoning)) return ch.message.content || ch.message.reasoning; if (typeof ch.text === 'string') return ch.text; }
  return '';
}
for (const item of $input.all()) {
  let raw = String(llmText(item.json) || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  if (!raw) continue;
  const a = raw.indexOf('['); const b = raw.lastIndexOf(']');
  const txt = (a !== -1 && b !== -1 && b > a) ? raw.slice(a, b + 1) : raw;
  let parsed; try { parsed = JSON.parse(txt); } catch (e) { continue; }
  const arr = Array.isArray(parsed) ? parsed : [parsed];
  for (const e of arr) results.push({ json: { activity_id: e.activity_id, companyName: e.companyName, sentiment: e.sentiment, reasoning: e.reasoning } });
}
return results;

const helpers=this.helpers;
const SRK='<REDACTED_SUPABASE_JWT>';
const SB='https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const H={apikey:SRK,Authorization:'Bearer '+SRK};
const ctx=$("Build Context").first().json; const cfg=ctx.config||{};
const ew=(cfg.engagementWeights&&cfg.engagementWeights.X)||{like:1,reply:2,repost:10,quote:4};
const clamp=cfg.sentimentClamp||{min:0.5,max:1.3}; const halfLife=(cfg.halfLifeDays&&cfg.halfLifeDays.X)||7;
const nameSet=new Set((ctx.companies||[]).filter(c=>(c.type||'direct')!=='indirect').map(c=>c.name));
// company name -> its own x_handle (lowercased, no @). Used to DISCOUNT a company's OWN tweets:
// earned attention beats self-promotion, so own-account posts count least (mirrors the LinkedIn
// ternary company-tier) instead of getting boosted by the company's own follower count.
const cmap={}; for(const c of (ctx.companies||[])){ if(c&&c.name&&c.x_handle) cmap[c.name]=String(c.x_handle).toLowerCase().replace(/^@/,''); }
function normTerm(t){ if(!t)return''; let s=String(t).toLowerCase().trim().replace(/^[@#$]/,''); if(!/^[a-z0-9_.\-]{2,20}$/.test(s))return''; return s; }
function sentMult(s){ if(s==null)return 1.0; const x=Math.max(-3,Math.min(3,Number(s))); return clamp.min+((x+3)/6)*(clamp.max-clamp.min); }
function llmText(j){ if(j&&Array.isArray(j.choices)&&j.choices[0]){const ch=j.choices[0]; if(ch.message&&(ch.message.content||ch.message.reasoning))return ch.message.content||ch.message.reasoning; if(typeof ch.text==='string')return ch.text;} if(j&&typeof j.text==='string')return j.text; return ''; }
const full={}; for(const it of $('Prep X Batches').all()){ for(const t of (it.json.full||[])) full[String(t.id)]=t; }
const llm={};
for(const it of $input.all()){ let raw=String(llmText(it.json)||'').replace(/```json/gi,'').replace(/```/g,'').trim(); if(!raw)continue; const a=raw.indexOf('['),b=raw.lastIndexOf(']'); const txt=(a!==-1&&b!==-1&&b>a)?raw.slice(a,b+1):raw; let parsed; try{parsed=JSON.parse(txt);}catch(e){continue;} for(const e of (Array.isArray(parsed)?parsed:[parsed])){ if(e&&e.activity_id!=null) llm[String(e.activity_id)]=e; } }
const rows=[]; const learn={};
for(const id in full){
  const tw=full[id]; const e=llm[id]||{};
  const _co=(e&&Array.isArray(e.companies))?e.companies:((e&&e.companyName)?[{companyName:e.companyName,sentiment:e.sentiment,reasoning:e.reasoning}]:[]);
  const company_names=_co.filter(c=>c&&c.companyName&&nameSet.has(c.companyName)).map(c=>({name:c.companyName,sentiment:(c.sentiment!=null?c.sentiment:null),reasoning:c.reasoning||''}));
  const companyName=company_names.length?company_names[0].name:'NONE';
  const sentiment=(companyName!=='NONE'&&company_names[0].sentiment!=null)?company_names[0].sentiment:null;
  const reasoning=company_names.length?(company_names[0].reasoning||''):'';
  let post_weight=null; let tierB=null;
  if(companyName!=='NONE'){
    const eng=((ew.like!=null?ew.like:1)*Number(tw.likeCount||0))+((ew.reply!=null?ew.reply:2)*Number(tw.replyCount||0))+((ew.repost!=null?ew.repost:10)*Number(tw.retweetCount||0))+((ew.quote!=null?ew.quote:4)*Number(tw.quoteCount||0));
    // MINDSHARE MODEL (2026-07-08): reach = engagement only — viewCount removed from scoring (still stored on the row).
    const reach=Math.pow(Math.max(0,eng),49/50);
    const authorU=String(tw.authorUserName||'').toLowerCase().replace(/^@/,'');
    const ownH=cmap[companyName];
    const own=(ownH&&authorU&&authorU===ownH); // own post -> company tier, counts least
    const AB=cfg.authorBaseline||{company:1,employee:2,external:5};
    const AEM=cfg.authorEngMult||{company:1,employee:1.2,external:2};
    const B=own?(AB.company!=null?AB.company:1):(AB.external!=null?AB.external:5);
    const M=own?(AEM.company!=null?AEM.company:1):(AEM.external!=null?AEM.external:2);
    tierB=B;
    let age=0; if(tw.createdAt){const d=new Date(tw.createdAt); if(!isNaN(d))age=Math.max(0,(Date.now()-d.getTime())/86400000);}
    const decay=age<=7?1:Math.pow(2,-age/halfLife);
    post_weight=parseFloat(((B+reach*M)*sentMult(sentiment)*decay).toFixed(6));
  } else {
    const term=normTerm(e.rejectTerm); const col=e.collidesWith;
    if(term&&col&&nameSet.has(col)){ (learn[col]||(learn[col]=new Set())).add(term); }
  }
  // authorWeight column now stores the author-TIER baseline B (1 own / 5 external) — Decay reads it; no longer the follower tier.
  rows.push({id:tw.id,twitterUrl:tw.twitterUrl,url:tw.url,text:tw.text,createdAt:tw.createdAt||null,likeCount:tw.likeCount,retweetCount:tw.retweetCount,replyCount:tw.replyCount,quoteCount:tw.quoteCount,viewCount:tw.viewCount,followers:tw.followers,authorWeight:(tierB!=null?tierB:tw.authorWeight),sentiment,reasoning,companyName,company_names,post_weight});
}
let written=0;
if(rows.length){ try{ await helpers.httpRequest({method:'POST',url:SB+'/tweets?on_conflict=id',headers:Object.assign({},H,{'Content-Type':'application/json','Prefer':'resolution=merge-duplicates,return=minimal'}),body:rows,json:true}); written=rows.length; }catch(err){ return [{json:{error:'upsert failed: '+(err&&err.message||err)}}]; } }
let learnedCount=0; const learnKeys=Object.keys(learn);
if(learnKeys.length){ try{
  const cfgRows=await helpers.httpRequest({method:'GET',url:SB+'/sov_config?select=config&id=eq.1',headers:H,json:true});
  const conf=(cfgRows&&cfgRows[0]&&cfgRows[0].config)?cfgRows[0].config:{};
  const neg=(conf.xNegations&&typeof conf.xNegations==='object')?conf.xNegations:{};
  for(const co of learnKeys){ const existing=new Set((Array.isArray(neg[co])?neg[co]:[]).map(x=>String(x).toLowerCase())); const own=new Set([co.toLowerCase()]); for(const w of String(co).toLowerCase().split(/\s+/))own.add(w); for(const term of learn[co]){ if(existing.size>=25)break; if(existing.has(term)||own.has(term))continue; existing.add(term); learnedCount++; } neg[co]=Array.from(existing).slice(0,25); }
  conf.xNegations=neg;
  await helpers.httpRequest({method:'PATCH',url:SB+'/sov_config?id=eq.1',headers:Object.assign({},H,{'Content-Type':'application/json','Prefer':'return=minimal'}),body:{config:conf},json:true});
}catch(e){} }
const attributed=rows.filter(r=>r.post_weight!=null).length;
return [{json:{processed:rows.length,written,attributed,none:rows.length-attributed,learnedNegations:learnedCount}}];

// Re-attach rich fields from Flatten (by id) for the LLM: the upsert output only has DB columns, so
// authorUserName (needed to attribute a company's OWN tweets via handle match) would otherwise be lost.
const flat = {}; for (const it of $("Flatten X Data").all()) { const j = it.json; flat[String(j.id)] = j; }
return $input.all().map(it => { const j = it.json; const f = flat[String(j.id)] || {}; return { json: { id: String(j.id), text: (j.text || f.text || ""), authorUserName: (f.authorUserName || ""), foundBy: (f.foundBy || "") } }; });
